package com.configmonitor.app;
import org.json.*;import java.util.*;import android.content.*;
public final class Backups {
 static final String[] KEYS={"language","theme","failureLimit","interval","testUrl","targets","tone","volume","vibrate","gradual","resumeBoot","alertsEnabled","alertScheduleEnabled","alertDays","alertStart","alertEnd"};
 public static JSONObject create()throws JSONException{JSONArray nodes=new JSONArray(),all=App.db.all();for(int i=0;i<all.length();i++){JSONObject n=all.getJSONObject(i);nodes.put(App.j("raw",n.optString("raw"),"name",n.optString("name"),"type",n.optString("type"),"method",n.optString("method","HTTPS"),"enabled",n.optBoolean("enabled",true),"rules",n.optJSONObject("rules")));}JSONObject settings=new JSONObject();Map<String,?> prefs=App.prefs.getAll();for(String k:KEYS)if(prefs.containsKey(k))settings.put(k,prefs.get(k));String tone=settings.optString("tone","builtin:gentle");if(!tone.startsWith("builtin:"))settings.put("tone","builtin:gentle");return App.j("format",1,"created",System.currentTimeMillis(),"nodes",nodes,"settings",settings);}
 public static final class Prepared {final List<JSONObject> nodes;final JSONObject settings;Prepared(List<JSONObject> n,JSONObject p){nodes=n;settings=p;}}
 public static Prepared validate(JSONObject doc)throws Exception{
  if(doc.getInt("format")!=1)throw new IllegalArgumentException("Unsupported backup version");List<JSONObject> nodes=new ArrayList<>();JSONArray list=doc.getJSONArray("nodes");
  for(int i=0;i<list.length();i++){JSONObject src=list.getJSONObject(i);JSONObject n=src.optString("type").equals("server")?Parser.server(src.getString("raw"),src.optString("name"),src.optString("method","ICMP")):src.optString("type").equals("address")?Parser.address(src.getString("raw"),src.optString("name"),src.optString("method","HTTPS")):Parser.parse(src.getString("raw"));n.put("name",src.getString("name")).put("enabled",src.optBoolean("enabled",true));if(src.optJSONObject("rules")!=null)n.put("rules",Rules.validate(src.getJSONObject("rules")));nodes.add(n);}
  JSONObject p=doc.getJSONObject("settings"),safe=new JSONObject();String language=p.optString("language","fa"),theme=p.optString("theme","dark"),tone=p.optString("tone","builtin:gentle");if(!Arrays.asList("fa","en").contains(language)||!Arrays.asList("dark","light").contains(theme))throw new IllegalArgumentException("Invalid settings");if(!Arrays.asList("builtin:gentle","builtin:pulse","builtin:bell","builtin:urgent").contains(tone))tone="builtin:gentle";
  int failureLimit=p.optInt("failureLimit",6);if(failureLimit<1||failureLimit>100)throw new IllegalArgumentException("Invalid failure limit");safe.put("failureLimit",failureLimit);int interval=p.optInt("interval",20),volume=p.optInt("volume",80);if(interval<10||interval>3600||volume<0||volume>100)throw new IllegalArgumentException("Invalid settings");safe.put("language",language).put("theme",theme).put("tone",tone).put("interval",interval).put("volume",volume);
  JSONArray targets=new JSONArray(p.optString("targets","[]"));if(targets.length()==0)targets.put(p.optString("testUrl","https://www.gstatic.com/generate_204"));targets=Targets.validate(targets);safe.put("targets",targets.toString()).put("testUrl",targets.getString(0));for(String k:new String[]{"vibrate","gradual","resumeBoot"})safe.put(k,p.optBoolean(k,k.equals("vibrate")));boolean scheduled=p.optBoolean("alertScheduleEnabled",false);int days=p.optInt("alertDays",127),start=p.optInt("alertStart",480),end=p.optInt("alertEnd",1380);AlertSchedule.validate(scheduled,days,start,end);safe.put("alertsEnabled",p.optBoolean("alertsEnabled",true)).put("alertScheduleEnabled",scheduled).put("alertDays",days).put("alertStart",start).put("alertEnd",end);return new Prepared(nodes,safe);
 }
 /** Restore appends deduplicated entries; never deletes existing monitors or history. */
 public static int restore(Prepared p)throws Exception{synchronized(App.db){Set<String> present=new HashSet<>();JSONArray all=App.db.all();for(int i=0;i<all.length();i++){JSONObject n=all.getJSONObject(i);present.add(identity(n));}int added=0;android.database.sqlite.SQLiteDatabase d=App.db.getWritableDatabase();d.beginTransaction();try{for(JSONObject n:p.nodes)if(present.add(identity(n))){App.db.save(n);added++;}d.setTransactionSuccessful();}finally{d.endTransaction();}SharedPreferences.Editor e=App.prefs.edit();Iterator<String> keys=p.settings.keys();while(keys.hasNext()){String k=keys.next();Object v=p.settings.get(k);if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof Number)e.putInt(k,((Number)v).intValue());else e.putString(k,v.toString());}e.putLong("alertsChangedAt",System.currentTimeMillis()).apply();Alerts.policyChanged();return added;}}
 static String identity(JSONObject n){return n.optString("type")+"\n"+n.optString("method")+"\n"+n.optString("raw");}
}
